  });

  // AC: @batch-exec ac-invalid-json
  // AC: @trait-semantic-exit-codes ac-2 — validation error exits non-zero
  it("rejects malformed JSON", () => {
    const result = kspec(
      `batch --commands 'not valid json'`,
